const books = $json.results || $json.data || [];

if (books.length === 0) {
  return [{ json: { noBooks: true, message: 'No hay libros nuevos para marketing' } }];
}

// Procesar cada libro y generar copy para 3 canales
const marketingItems = [];

for (const book of books) {
  const props = book.properties || {};
  const title = props.Nombre?.title?.[0]?.plain_text || 'Sin titulo';
  const author = props.Autor?.rich_text?.[0]?.plain_text || 'Autor desconocido';
  const isbn = props.ISBN?.rich_text?.[0]?.plain_text || '';
  const sku = props.SKU?.number || props.SKU?.formula_string || '';
  const genre = props.Genero?.select?.name || 'Otros';
  const year = props.Año?.number || '';
  const price = props['Precio venta']?.number || 0;
  const coverUrl = props.Portada?.url || '';
  const webUrl = props['Enlace web']?.url || '';
  const synopsis = props.Sinopsis?.rich_text?.[0]?.plain_text || '';
  const condition = props['Estado fisico']?.select?.name || '';
  const pageId = book.id;

  // Hashtags por genero
  const genreHashtags = {
    'Novela': '#novela #literatura #lectura',
    'Novela historica': '#novelahistorica #historia #literatura',
    'Ciencia ficcion': '#cienciaficcion #scifi #literatura',
    'Fantasia': '#fantasia #libros #lectura',
    'Terror': '#terror #libros #misterio',
    'Thriller': '#thriller #misterio #suspense',
    'Ensayo': '#ensayo #no ficcion #cultura',
    'Poesia': '#poesia #literatura #versos',
    'Teatro': '#teatro #literatura #drama',
    'Infantil': '#infantil #libros #ninos',
    'Biografia': '#biografia #no ficcion #historia',
    'Historia': '#historia #no ficcion #cultura',
    'Otros': '#libros #lectura #segundamano'
  };

  const hashtags = genreHashtags[genre] || genreHashtags['Otros'];
  const extraTags = '#segundavuelta #librossegundamano #jerez #libreria';
  const allHashtags = hashtags + ' ' + extraTags;

  // Fecha sugerida (manana + offset por canal)
  const tomorrow = new Date();
  tomorrow.setDate(tomorrow.getDate() + 1);
  const formatDate = (d) => d.toISOString().split('T')[0];

  // --- COPY INSTAGRAM ---
  const igShort = `Nuevo en Segunda Vuelta: "${title}" de ${author}`;
  const igLong = `Nuevo libro en la libreria.

"${title}" de ${author}` + (year ? ` (${year})` : '') + `

${genre ? 'Genero: ' + genre + '\n' : ''}${condition ? 'Estado: ' + condition + '\n' : ''}Precio: ${price} eur

` + (synopsis ? synopsis.substring(0, 150) + '...' : 'Una gran lectura te espera.') + `

Disponible en nuestra tienda online.

${allHashtags}`;

  marketingItems.push({
    bookTitle: title,
    bookAuthor: author,
    isbn: isbn,
    sku: String(sku),
    genre: genre,
    price: price,
    coverUrl: coverUrl,
    webUrl: webUrl,
    pageId: pageId,
    channel: 'Instagram',
    estado: 'Borrador',
    fechaSugerida: formatDate(tomorrow),
    copyCorto: igShort,
    copyLargo: igLong,
    hashtags: allHashtags
  });

  // --- COPY FACEBOOK ---
  const fbShort = `Acaba de llegar: "${title}" de ${author}`;
  const fbLong = `Tengo una novedad en Segunda Vuelta Libros.

"${title}" de ${author}` + (year ? ` (${year})` : '') + `

` + (genre ? 'Genero: ' + genre + '\n' : '') + (condition ? 'Estado: ' + condition + '\n' : '') + `Precio: ${price} eur

` + (synopsis ? synopsis.substring(0, 200) + '...' : 'Una lectura que no te puedes perder.') + `

Si te interesa, escribeme o pasate por la tienda online. ¡No tardes, que es unico ejemplar!

${hashtags} ${extraTags}`;

  marketingItems.push({
    bookTitle: title,
    bookAuthor: author,
    isbn: isbn,
    sku: String(sku),
    genre: genre,
    price: price,
    coverUrl: coverUrl,
    webUrl: webUrl,
    pageId: pageId,
    channel: 'Facebook',
    estado: 'Borrador',
    fechaSugerida: formatDate(new Date(tomorrow.getTime() + 86400000)),
    copyCorto: fbShort,
    copyLargo: fbLong,
    hashtags: allHashtags
  });

  // --- COPY NEWSLETTER ---
  const nlShort = `Novedad: ${title} - ${author}`;
  const nlLong = `Hola,

Esta semana te traemos una novedad especial:

"${title}" de ${author}` + (year ? ` (${year})` : '') + `

` + (genre ? 'Genero: ' + genre + '\n' : '') + (condition ? 'Estado: ' + condition + '\n' : '') + `Precio: ${price} eur

` + (synopsis ? synopsis.substring(0, 300) + '...' : 'Una lectura que te enganchara.') + `

Disponible en nuestra tienda: ${webUrl || 'consultanos'}

Un saludo,
Segunda Vuelta Libros`;

  marketingItems.push({
    bookTitle: title,
    bookAuthor: author,
    isbn: isbn,
    sku: String(sku),
    genre: genre,
    price: price,
    coverUrl: coverUrl,
    webUrl: webUrl,
    pageId: pageId,
    channel: 'Newsletter',
    estado: 'Borrador',
    fechaSugerida: formatDate(new Date(tomorrow.getTime() + 172800000)),
    copyCorto: nlShort,
    copyLargo: nlLong,
    hashtags: ''
  });
}

return marketingItems.map(item => ({ json: item }));

// Recopilar todos los libros procesados
const allBooks = $('Generar Copy').all().map(r => r.json);
const uniqueBooks = [];
const seen = new Set();
for (const b of allBooks) {
  if (!seen.has(b.pageId)) {
    seen.add(b.pageId);
    uniqueBooks.push(b);
  }
}

return [{
  json: {
    booksCount: uniqueBooks.length,
    draftsCount: allBooks.length,
    bookTitles: uniqueBooks.map(b => b.bookTitle + ' (' + b.bookAuthor + ')').join('\n'),
    fecha: new Date().toLocaleDateString('es-ES')
  }
}];

